select pg_advisory_xact_lock(1846237911);

create temporary table market_economy_replay_seed (
    game_date date not null,
    player_id varchar(64) not null,
    actual_net_points_micros bigint not null,
    expected_net_points_micros bigint not null,
    dividend_cents bigint not null,
    actual_minutes_micros bigint not null,
    projected_minutes_micros bigint,
    qualifies_for_instruments boolean not null,
    primary key (game_date, player_id)
) on commit drop;

;

create or replace function public.market_reject_legacy_starting_cash()
returns trigger
language plpgsql
set search_path = pg_catalog, public
as $function$
begin
    if new.cash_cents = 14000000000 then
        raise exception using
            errcode = '55000',
            message = 'legacy $140M market worker rejected';
    end if;
    return new;
end;
$function$;

revoke all on function public.market_reject_legacy_starting_cash()
    from public;

drop trigger if exists market_accounts_reject_legacy_starting_cash
    on public.market_accounts;
create trigger market_accounts_reject_legacy_starting_cash
before insert on public.market_accounts
for each row execute function public.market_reject_legacy_starting_cash();

create or replace function public.market_guard_settlement_economy()
returns trigger
language plpgsql
set search_path = pg_catalog, public
as $function$
declare
    persisted_bias bigint;
    persisted_rate numeric;
begin
    persisted_bias := (
        new.calculation_inputs ->> 'expectation_bias_micros'
    )::bigint;
    persisted_rate := (
        new.calculation_inputs ->> 'dollars_per_net_point'
    )::numeric;

    if persisted_bias is distinct from 435865 then
        raise exception using
            errcode = '55000',
            message = 'unsupported settlement economy parameters';
    end if;

    if new.event_type = 'original' then
        if new.formula_version is distinct from
                'net-points-v1+dnt-bias-0.43586495+usd-80000'
            or persisted_rate is distinct from 80000 then
            raise exception using
                errcode = '55000',
                message = 'legacy settlement worker rejected';
        end if;
    elsif new.event_type = 'adjustment' then
        if (
            (
                new.formula_version =
                    'net-points-v1+dnt-bias-0.43586495+usd-80000'
                and persisted_rate = 80000
            )
            or (
                new.formula_version =
                    'net-points-v1+dnt-bias-0.43586495+usd-40000'
                and persisted_rate = 40000
            )
        ) is distinct from true then
            raise exception using
                errcode = '55000',
                message = 'unsupported settlement adjustment economy';
        end if;
    else
        raise exception using
            errcode = '55000',
            message = 'unsupported settlement event type';
    end if;

    return new;
end;
$function$;

revoke all on function public.market_guard_settlement_economy()
    from public;

do $settlement_guard$
begin
    if to_regclass('public.market_production_settlement_events')
            is not null then
        execute 'drop trigger if exists market_settlement_economy_guard on public.market_production_settlement_events';
        execute 'create trigger market_settlement_economy_guard before insert on public.market_production_settlement_events for each row execute function public.market_guard_settlement_economy()';
    end if;
end;
$settlement_guard$;

do $migration$
declare
    seed_count bigint;
begin
    if not exists (
        select 1
        from supabase_migrations.schema_migrations
        where version = '20260815000000'
    ) then
        lock table public.market_accounts, public.market_replay_events,
            public.market_settlements in access exclusive mode;

        if exists (select 1 from public.market_settlements) then
            raise exception 'cannot rebase market economy after historical settlements exist';
        end if;

        select count(*) into seed_count
        from market_economy_replay_seed;
        if seed_count <> 2126 then
            raise exception 'canonical economy seed count mismatch';
        end if;
        if (select count(*) from public.market_replay_events)
            <> seed_count then
            raise exception 'market replay event count mismatch';
        end if;
        if (
            select count(*)
            from public.market_replay_events as event
            join market_economy_replay_seed as seed
              using (game_date, player_id)
        ) <> seed_count then
            raise exception 'market replay event identity mismatch';
        end if;
        if exists (
            select 1
            from public.market_replay_events as event
            join market_economy_replay_seed as seed
              using (game_date, player_id)
            where event.actual_net_points_micros
                    <> seed.actual_net_points_micros
               or event.expected_net_points_micros
                    <> seed.expected_net_points_micros
               or event.actual_minutes_micros
                    <> seed.actual_minutes_micros
               or event.projected_minutes_micros
                    is distinct from seed.projected_minutes_micros
               or event.qualifies_for_instruments
                    <> seed.qualifies_for_instruments
        ) then
            raise exception 'canonical replay inputs changed';
        end if;

        alter table public.market_accounts
            alter column cash_cents set default 20782400000;

        update public.market_accounts
        set cash_cents = cash_cents + 6782400000,
            version = case
                when version = 0 then 0
                else version + 1
            end,
            updated_at = timezone('utc', now());

        update public.market_portfolio_snapshots
        set cash_cents = cash_cents + 6782400000,
            free_cash_cents = free_cash_cents + 6782400000,
            total_value_cents = total_value_cents + 6782400000;

        update public.market_replay_events as event
        set dividend_cents = seed.dividend_cents
        from market_economy_replay_seed as seed
        where event.game_date = seed.game_date
          and event.player_id = seed.player_id
          and event.dividend_cents is distinct from
              seed.dividend_cents;

    end if;
end;
$migration$;
